function sanitize(raw){if(!raw||typeof raw!=='object'||!Array.isArray(raw.notes)||!Array.isArray(raw.completed))throw Error('Invalid workspace');const result={...state,notes:raw.notes.filter(n=>n&&typeof n.title==='string'&&typeof n.body==='string'&&Number.isInteger(n.stage)&&n.stage>=0&&n.stage<9).map(n=>({id:typeof n.id==='string'?n.id:uid(),title:n.title.slice(0,150),body:n.body.slice(0,100000),stage:n.stage,created:typeof n.created==='string'?n.created:new Date().toISOString(),updated:typeof n.updated==='string'?n.updated:null})),completed:[...new Set(raw.completed.filter(i=>Number.isInteger(i)&&i>=0&&i<9))],drafts:{},quiz:{},checks:[],last:Number.isInteger(raw.last)&&raw.last>=0&&raw.last<9?raw.last:0,noteDraft:{title:'',body:'',stage:0}};for(let i=0;i<9;i++){if(typeof raw.drafts?.[i]==='string')result.drafts[i]=raw.drafts[i].slice(0,100000);if(Number.isInteger(raw.quiz?.[i])&&raw.quiz[i]>=0&&raw.quiz[i]<3)result.quiz[i]=raw.quiz[i]}if(Array.isArray(raw.checks))result.checks=[...new Set(raw.checks.filter(x=>typeof x==='string'&&/^\d-[0-2]$/.test(x)))];if(raw.noteDraft&&typeof raw.noteDraft.title==='string'&&typeof raw.noteDraft.body==='string')result.noteDraft={title:raw.noteDraft.title.slice(0,150),body:raw.noteDraft.body.slice(0,100000),stage:Number.isInteger(raw.noteDraft.stage)&&raw.noteDraft.stage>=0&&raw.noteDraft.stage<9?raw.noteDraft.stage:0};if(raw.editDraft&&typeof raw.editDraft.id==='string'&&typeof raw.editDraft.title==='string'&&typeof raw.editDraft.body==='string'&&Number.isInteger(raw.editDraft.stage)&&raw.editDraft.stage>=0&&raw.editDraft.stage<9)result.editDraft={id:raw.editDraft.id,title:raw.editDraft.title.slice(0,150),body:raw.editDraft.body.slice(0,100000),stage:raw.editDraft.stage};result.resume=raw.resume&&Number.isInteger(raw.resume.lesson)&&raw.resume.lesson>=0&&raw.resume.lesson<9&&['learn','example','write','check'].includes(raw.resume.step)?{lesson:raw.resume.lesson,step:raw.resume.step}:null;result.learningLab=window.REILearningLab.normalize(raw.learningLab);result.learningPath=window.REILearningPathCore.normalize(raw.learningPath);result.researchLibrary=window.REILibraryCore?.normalizeSession(raw.researchLibrary)||null;result.researchSupport=window.REISupportCore?.normalize(raw.researchSupport)||null;return result}
