document.addEventListener('change',async e=>{if(e.target.dataset.readiness){const k=e.target.dataset.readiness;state.checks=e.target.checked?[...new Set([...state.checks,k])]:state.checks.filter(x=>x!==k);save();$('#readiness-count').textContent=state.checks.length+' of 27 checks complete';$('#check-progress').style.width=state.checks.length/27*100+'%'}if(e.target.id==='backup-file'){pendingImport=null;try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Choose a backup smaller than 5 MB.');const raw=JSON.parse(await f.text());if(raw.version!==2||!Array.isArray(raw.notes)||!Array.isArray(raw.completed)||!raw.drafts||typeof raw.drafts!=='object')throw Error('This is not a supported REI backup.');pendingImport=sanitize(raw);$('#import-preview').innerHTML=`<p><strong>${pendingImport.notes.length} ideas, ${Object.keys(pendingImport.drafts).length} drafts, ${pendingImport.completed.length} completed milestones, ${Object.values(pendingImport.learningPath.fields).filter(x=>x.trim()).length} learning notes and ${Object.values(pendingImport.learningPath.practice).filter(x=>x.attempt.trim()||x.revision.trim()).length} practice records.</strong></p><p>Restoring replaces this browser’s current learning workspace, including saved Create drafts, challenge choices, the guided workbook and practice. Download a backup first if you want to keep it.</p><div class="actions"><button class="button secondary" data-action="backup">Back up current workspace</button><button class="button primary" data-action="confirm-import">Replace and restore</button></div>`}catch(err){$('#import-preview').textContent='Could not read the backup. '+err.message}}});
document.addEventListener('submit',e=>{if(e.target.id==='quiz-form'){e.preventDefault();const i=+e.target.dataset.stage,answer=new FormData(e.target).get('answer');if(answer===null){$('#quiz-feedback').innerHTML='<div class="quiz-feedback wrong">Choose an answer first.</div>';return}state.quiz[i]=+answer;save();$('#quiz-feedback').innerHTML=quizFeedback(i,+answer)}if(e.target.id==='note-form'){e.preventDefault();const title=$('#note-title').value.trim(),body=$('#note-body').value.trim(),stage=+$('#note-stage').value;if(!title||!body){$('#note-status').textContent='Add a title and your thinking before saving.';return}if(editing){const n=state.notes.find(x=>x.id===editing);if(n)Object.assign(n,{title,body,stage,updated:new Date().toISOString()});editing=null;state.editDraft=null}else{state.notes.unshift({id:uid(),title,body,stage,created:new Date().toISOString(),updated:null});state.noteDraft={title:'',body:'',stage:0}}const ok=save();$('#editor-wrap').innerHTML=noteEditor();refreshNotes();toast(ok?'Idea saved to your notebook.':'Idea kept for this session. Export a backup to keep it.')}});
